import{_ as a,c as t,o as n,ag as i}from"./chunks/framework.Vyheyqg9.js";const p=JSON.parse('{"title":"A03 — EC2, EBS, load balancing and Auto Scaling","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-03.md","filePath":"practice/aws/associate-03.md"}'),o={name:"practice/aws/associate-03.md"};function s(r,e,l,c,d,u){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="a03-—-ec2-ebs-load-balancing-and-auto-scaling" tabindex="-1">A03 — EC2, EBS, load balancing and Auto Scaling <a class="header-anchor" href="#a03-—-ec2-ebs-load-balancing-and-auto-scaling" aria-label="Permalink to “A03 — EC2, EBS, load balancing and Auto Scaling”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/compute-and-scaling.html">compute and scaling</a>.</p><p><a href="/aws-homework/sources/associate-03.txt">Original supplied text</a>.</p><h2 id="a03-1-—-static-website-on-ec2" tabindex="-1"><span class="hub-section-number">1 </span>A03.1 — Static website on EC2 <a class="header-anchor" href="#a03-1-—-static-website-on-ec2" aria-label="Permalink to “1 A03.1 — Static website on EC2”">​</a></h2><ul><li>[ ] Create <code>CloudX-Web-SG</code>: public HTTP/HTTPS, SSH only from your current IP, and the specified outbound access.</li><li>[ ] Create <code>CloudX-App-Private-SG</code> allowing the source-specified traffic from <code>CloudX-Web-SG</code>.</li><li>[ ] Launch a suitable Linux instance with a key pair and user data installing Apache or your selected Nginx equivalent. Verify the initial HTTP page.</li><li>[ ] Transfer sample static content to the server directory; verify the changed page. Build/deploy one supplied shop frontend or a compatible chosen app.</li><li>[ ] Use the IAM profiles from A02 to compare permission to stop/start the instance.</li></ul><h2 id="a03-2-—-cli-launch-and-changing-ssh-source-—-promoted-from-optional-repeating-a03-1" tabindex="-1"><span class="hub-section-number">2 </span>A03.2 — CLI launch and changing SSH source — promoted from optional; repeating A03.1 <a class="header-anchor" href="#a03-2-—-cli-launch-and-changing-ssh-source-—-promoted-from-optional-repeating-a03-1" aria-label="Permalink to “2 A03.2 — CLI launch and changing SSH source — promoted from optional; repeating A03.1”">​</a></h2><ul><li>[ ] Launch an instance with user data through CLI, verify it and terminate that disposable instance.</li><li>[ ] Write a script for your chosen OS that updates the SSH ingress source when your public IP changes. Replace the pasted source&#39;s malformed dash/argument examples with valid commands. Remove obsolete ingress instead of accumulating old allowed IPs.</li></ul><h2 id="a03-3-—-custom-node-js-ami" tabindex="-1"><span class="hub-section-number">3 </span>A03.3 — Custom Node.js AMI <a class="header-anchor" href="#a03-3-—-custom-node-js-ami" aria-label="Permalink to “3 A03.3 — Custom Node.js AMI”">​</a></h2><ul><li>[ ] Launch an instance, install Node.js and selected process tools for the intended OS user, and create <code>CloudXNodejsAMI</code>.</li><li>[ ] After image creation, terminate the source instance and launch a replacement from that AMI. Verify the tools survive through the image, not an undeclared manual reinstall.</li></ul><h2 id="a03-4-—-backend-and-frontend-integration" tabindex="-1"><span class="hub-section-number">4 </span>A03.4 — Backend and frontend integration <a class="header-anchor" href="#a03-4-—-backend-and-frontend-integration" aria-label="Permalink to “4 A03.4 — Backend and frontend integration”">​</a></h2><ul><li>[ ] Deploy the course backend (the <code>feat/ec2-lab</code> branch where applicable) or a compatible chosen backend and verify its port-80 endpoint.</li><li>[ ] <strong>Promoted from optional:</strong> point the frontend at that backend, rebuild/redeploy and verify real browser API requests, including correct CORS behavior. <strong>Repeating P03&#39;s HTTP capability through EC2 hosting.</strong></li></ul><h2 id="a03-5-—-ebs-persistence" tabindex="-1"><span class="hub-section-number">5 </span>A03.5 — EBS persistence <a class="header-anchor" href="#a03-5-—-ebs-persistence" aria-label="Permalink to “5 A03.5 — EBS persistence”">​</a></h2><ul><li>[ ] Create/attach a volume, prepare/mount it appropriately, write test files, safely unmount/detach it and attach it to another compatible instance. Verify the files, then delete the disposable volume. Keep attachment AZ requirements in mind.</li></ul><h2 id="a03-6-—-alb-and-auto-scaling" tabindex="-1"><span class="hub-section-number">6 </span>A03.6 — ALB and Auto Scaling <a class="header-anchor" href="#a03-6-—-alb-and-auto-scaling" aria-label="Permalink to “6 A03.6 — ALB and Auto Scaling”">​</a></h2><ul><li>[ ] Create <code>CloudX-ALB-SG</code> for public HTTP and <code>CloudX-EC2-SG</code> permitting HTTP from the ALB security group.</li><li>[ ] Create <code>CloudXWebAMI</code> from a web-server instance and use it in <code>CloudXALBLaunchConfig</code> as the course launch template/configuration reference. Preserve the task name while using the supported template mechanism.</li><li>[ ] Create <code>CloudX-ALB</code> in two AZs and <code>CloudXTargetGroup</code> with <code>/index.html</code> health checks.</li><li>[ ] Configure <code>CloudX-ASG</code> with minimum 2, maximum 4 and CPU target 75%; inspect healthy targets and traffic distribution.</li><li>[ ] <strong>Promoted from optional:</strong> enable stickiness and compare traffic distribution. Repeated requests must be distinguishable by target to demonstrate the effect.</li><li>[ ] After verification, reduce capacity to the source&#39;s idle 0–1 range with desired 0, or remove the disposable group. Remove unused load balancers, volumes and AMIs/snapshots; stopping an instance alone is not complete cleanup.</li></ul><h2 id="completion-evidence" tabindex="-1"><span class="hub-section-number">7 </span>Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “7 Completion evidence”">​</a></h2><ul><li>[ ] Record observed results for every section, including all promoted extensions.</li><li>[ ] Retain configuration/code, successful and denied/failing cases where specified, and actual cleanup state.</li><li>[ ] Link earlier evidence for repeating work and add the new interface/behavior comparison.</li></ul><p>Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>; never claim screenshots or sample code complete independent work.</p>',19)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
